    out = [row[:] for row in grid]
    # Each non-1 marker on the horizontal line grows a four-cell stem upward.
    r = next((i for i, row in enumerate(grid) if any(v in (2, 8) for v in row)), None)
    if r is None:
        return out
    for c, v in enumerate(grid[r]):
        if v in (2, 8):
            for k in range(1, 5):
                if r-k >= 0:
                    out[r-k][c] = 1 if k > 1 else v
    return out
